/** Newest first — the reading order for both the preview and the full timeline. */
export const timelineNewestFirst: TimelineEvent[] = [...timelineEvents].reverse();

/** The curated subset the Collaborations preview shows. */
export function recentEvents(count: number): TimelineEvent[] {
  return timelineNewestFirst.slice(0, count);
}

/**
 * Parse "YYYY-MM-DD" as a LOCAL date. `new Date(iso)` treats a bare ISO date as
 * UTC midnight, which renders as the *previous* day anywhere west of Greenwich
 * (Oct 26 → "Oct 25" in Los Angeles). Splitting the parts sidesteps that.
 */
function parseLocalDate(iso: string): Date {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, m - 1, d);
}

const LONG_DATE = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

/** "Oct 26, 2024" — or the hand-written label when the date is only approximate. */
export function formatEventDate(event: TimelineEvent): string {
  if (event.dateApprox && event.dateLabel) return event.dateLabel;
  return LONG_DATE.format(parseLocalDate(event.date));
}

/**
 * The two lines of the preview's date block. Approximate dates can't show a day
 * number, so they lead with the month instead — and it keeps a label like
 * "October 3 (verify year)" from blowing out a 56px-wide block at 375px.
 */
export function dateBlock(event: TimelineEvent): { primary: string; secondary: string } {
  const d = parseLocalDate(event.date);
  const month = d.toLocaleString("en-US", { month: "short" }).toUpperCase();

  if (event.dateApprox) {
    return { primary: month, secondary: String(d.getFullYear()) };
  }
  return { primary: String(d.getDate()), secondary: `${month} ${d.getFullYear()}` };
}

/** Years present in the data, newest first — the spine markers on the full timeline. */
export const timelineYears: number[] = [
  ...new Set(timelineNewestFirst.map((e) => parseLocalDate(e.date).getFullYear())),
];

/** He was billed under several aliases; only call it out when it isn't plain "SKIM". */
export function isAliasBilling(billedAs: string): boolean {
  return billedAs.trim().toLowerCase() !== "skim";
}

export function eventYear(event: TimelineEvent): number {
  return parseLocalDate(event.date).getFullYear();
}
